#[test]
fn decibel_volts() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(
            AmplitudeRatio::from_decibel_volts(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x;
        assert_close(
            AmplitudeRatio::from_base(base).as_decibel_volts(),
            back,
            F64_TOL,
        );
        assert_close(
            AmplitudeRatio::from_decibel_volts(v).as_decibel_volts(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            AmplitudeRatio::from_decibel_volts(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            AmplitudeRatio::from_base(base as f32).as_decibel_volts() as f64,
            back,
            F32_TOL,
        );
    }
}

