#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "dBV".parse::<AmplitudeRatioUnit>(),
        Ok(AmplitudeRatioUnit::DecibelVolt)
    );
    assert_eq!(
        format!("2.5 {}", "dBV").parse::<AmplitudeRatio>(),
        Ok(AmplitudeRatio::new(2.5, AmplitudeRatioUnit::DecibelVolt))
    );
    assert_eq!(
        "dBµV".parse::<AmplitudeRatioUnit>(),
        Ok(AmplitudeRatioUnit::DecibelMicrovolt)
    );
    assert_eq!(
        format!("2.5 {}", "dBµV").parse::<AmplitudeRatio>(),
        Ok(AmplitudeRatio::new(
            2.5,
            AmplitudeRatioUnit::DecibelMicrovolt
        ))
    );
    assert_eq!(
        "dBmV".parse::<AmplitudeRatioUnit>(),
        Ok(AmplitudeRatioUnit::DecibelMillivolt)
    );
    assert_eq!(
        format!("2.5 {}", "dBmV").parse::<AmplitudeRatio>(),
        Ok(AmplitudeRatio::new(
            2.5,
            AmplitudeRatioUnit::DecibelMillivolt
        ))
    );
    assert_eq!(
        "dBu".parse::<AmplitudeRatioUnit>(),
        Ok(AmplitudeRatioUnit::DecibelUnloaded)
    );
    assert_eq!(
        format!("2.5 {}", "dBu").parse::<AmplitudeRatio>(),
        Ok(AmplitudeRatio::new(
            2.5,
            AmplitudeRatioUnit::DecibelUnloaded
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<AmplitudeRatio>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn point_arithmetic() {
    let a = AmplitudeRatio::from_base(6.0);
    let b = AmplitudeRatio::from_base(2.0);
    let d: Level = a - b;
    assert_eq!(d.as_base(), 4.0);
    assert_eq!(b + d, a);
    assert_eq!(d + b, a);
    assert_eq!(a - d, b);
    assert_eq!(a / b, 3.0);
    let mut c = b;
    c += d;
    assert_eq!(c, a);
    c -= d;
    assert_eq!(c, b);
    let i: Level<i64> = AmplitudeRatio::<i64>::from_base(7) - AmplitudeRatio::from_base(2);
    assert_eq!(i.as_base(), 5);
}
